import torch
@torch.no_grad()
def transfer(recv, src_rl, src_sft, sel, alpha=1.0):
    for n, p in recv.named_parameters():
        p.add_(alpha * sel(src_rl[n] - src_sft[n]))  # 隔离后注入

def decisive_step(traj, run_tests, apply):
    for t in range(1, len(traj.steps) + 1):
        if run_tests(apply(traj.steps[:t])) == "pass":
            return t, traj.steps[t - 1]   # 首步由败转胜
    return None, None

import torch.nn.functional as F
def ar_class_prob(logits_list, tok_ids):
    lp = 0.0
    for t, lg in enumerate(logits_list):
        lp = lp + F.log_softmax(lg, -1)[tok_ids[t]]
    return lp.exp()                         # 类别名序列概率

def pass_rate(samples, sat):
    ok = 0
    for s in samples:
        if all(sat(c, s["code"]) for c in s["required"]):
            ok += 1
    return ok / len(samples)

def realization(samples, sat, infer, gen):
    scores = []
    for s in samples:
        r_hat = infer(s["image"], s["layer_meta"])   # 推断需求
        code = gen(s["image"], s["layer_meta"], r_hat)
        hit = [sat(c, code) for c in s["required"]]
        scores.append(sum(hit) / len(hit))
    return sum(scores) / len(scores)
